entries[32753] = { ["name"] = "Pattern: Swiftheal Mantle", ["text"] = "Requires Tailoring (375)\nUse: Teaches you how to sew a Swiftheal Mantle.\nSell Price:\nSwiftheal Mantle\nBinds when picked up\nShoulder Cloth\n177 Armor\n+21 Stamina\n+16 Intellect\n+28 Spirit\nDurability 60 / 60\nRequires Level 70\nEquip: Improves spell haste rating by 27.\n\nEquip: Increases healing done by up to 84 and damage done by up to 28 for all magical spells and effects.\nSell Price:\nRequires Bolt of Imbued Netherweave (4), Primal Mooncloth (2), Primal Life (6), Heart of Darkness (2)" }
entries[32754] = { ["name"] = "Pattern: Bracers of Nimble Thought", ["text"] = "Binds when picked up\nRequires Tailoring (375)\nUse: Teaches you how to sew Bracers of Nimble Thought.\nSell Price:\nBracers of Nimble Thought\nBinds when equipped\nWrist Cloth\n103 Armor\n+27 Stamina\n+20 Intellect\nDurability 35 / 35\nRequires Level 70\nEquip: Improves spell haste rating by 28.\n\nEquip: Increases damage and healing done by magical spells and effects by up to 34.\nSell Price:\nRequires Bolt of Imbued Netherweave (3), Spellcloth (4), Primal Mana (8), Heart of Darkness (4)" }
entries[32755] = { ["name"] = "Pattern: Mantle of Nimble Thought", ["text"] = "Requires Tailoring (375)\nUse: Teaches you how to sew a Mantle of Nimble Thought.\nSell Price:\nMantle of Nimble Thought\nBinds when picked up\nShoulder Cloth\n177 Armor\n+37 Stamina\n+26 Intellect\nDurability 60 / 60\nRequires Level 70\nEquip: Improves spell haste rating by 38.\n\nEquip: Increases damage and healing done by magical spells and effects by up to 44.\nSell Price:\nRequires Bolt of Imbued Netherweave (4), Spellcloth (2), Primal Mana (6), Heart of Darkness (2)" }
entries[32756] = { ["name"] = "Gyro-Balanced Khorium Destroyer", ["text"] = "Binds when equipped\nRanged Gun\n148 - 275 Damage Speed 2.80\n(75.54 damage per second)\n+27 Stamina\n\nYellow Socket\nSocket Bonus: +3 Stamina\n\nDurability 90 / 90\nRequires Level 70\nSell Price:" }
entries[32757] = { ["name"] = "Blessed Medallion of Karabor", ["text"] = "Binds when picked up\nUnique\nNeck\n+49 Stamina\n+40 Shadow Resistance\nUse: Teleports the bearer to the footsteps of Illidan's fortress. (15 Min Cooldown)\n\"Once worn by a cleric of Karabor, this item allows the wearer entry into the Black Temple.\"" }
entries[32758] = { ["name"] = "Brute Cologne", ["text"] = "Use: Splash it all over to unleash the sophisticated ogre inside. Creatures of all kinds will be certain to notice you from afar.\n\nOnly works in Blade's Edge Mountains.\n\"A delicate fragrance for the discerning ogre.\"\nSell Price:" }
entries[32759] = { ["name"] = "Accelerator Module", ["text"] = "Binds when picked up\nUnique\n\"Used to activate any of the proton accelerator controllers at Bash'ir Landing.\"\nSell Price:" }
entries[32760] = { ["name"] = "The Macho Gnome's Arrow", ["text"] = "Binds when picked up\nAmmo Arrow\nAdds 53 damage per second\nRequires Level 70\n\"Fletched by Andy \"The Macho Gnome\" Savage.\"\nSell Price:" }
entries[32761] = { ["name"] = "The Sarge's Bullet", ["text"] = "Binds when picked up\nAmmo Bullet\nAdds 53 damage per second\nRequires Level 70\n\"More Pew Pew, Less QQ\"\nSell Price:" }
entries[32762] = { ["name"] = "Rulkster's Brain Juice", ["text"] = "Requires Level 55\n\nUse: Restores 1800 to 3000 mana. (2 Min Cooldown)\n\"Don't be a dummy. Drink your brain juice!\"\nSell Price:" }
entries[32763] = { ["name"] = "Rulkster's Secret Sauce", ["text"] = "Requires Level 55\n\nUse: Restores 1500 to 2500 health. (2 Min Cooldown)\n\"Drink to live.\"\nSell Price:" }
entries[32764] = { ["name"] = "Flaskataur's Celestial Brew", ["text"] = "Requires Level 65\n\nUse: Increases maximum health by 500 and defense rating by 10 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n\"Flasky essence captured from the mythical beast!\"\nSell Price:" }
entries[32765] = { ["name"] = "Flaskataur's Tears", ["text"] = "Requires Level 65\n\nUse: Increases attack power by 120 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n\"The distilled tears of the elusive Flaskataur.\"\nSell Price:" }
entries[32766] = { ["name"] = "Flaskataur's Flask of Flaskocity", ["text"] = "Requires Level 65\n\nUse: Increases mana regeneration by 25 mana per 5 seconds for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n\"Bears the mark of Flaskataur.\"\nSell Price:" }
entries[32767] = { ["name"] = "Flaskataur's Flask of Pretty Good Power", ["text"] = "Requires Level 50\n\nUse: Increases damage done by magical spells and effects by up to 70 for 2 hrs. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\n\"It's not supreme but it's not bad either.\"\nSell Price:" }
entries[32768] = { ["name"] = "Reins of the Raven Lord", ["text"] = "Binds when picked up\nUnique\nMount\nRequires Level 70\nRequires Riding (150)\n\nUse: Summons and dismisses a giant raven steed. This is a very fast mount. (3 Sec Cooldown)" }
entries[32769] = { ["name"] = "Belt of the Raven Lord", ["text"] = "Binds when picked up\nWaist Leather\n234 Armor\n+25 Strength\n+17 Agility\n+22 Stamina\n\nRed Socket\nBlue Socket\nSocket Bonus: +3 Agility\n\nDurability 35 / 35\nRequires Level 70\nSell Price:" }
entries[32770] = { ["name"] = "Skyguard Silver Cross", ["text"] = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\nRequires Sha'tari Skyguard\n- Exalted\nEquip: Improves critical strike rating by 34.\n\nEquip: 50% chance to increase your attack power by 140 for 30 sec when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds. (Proc chance: 50%, 10s cooldown)\nSell Price:" }
entries[32771] = { ["name"] = "Airman's Ribbon of Gallantry", ["text"] = "Binds when picked up\nUnique\nTrinket\nRequires Level 70\nRequires Sha'tari Skyguard\n- Exalted\nEquip: Improves spell critical strike rating by 34.\n\nEquip: 50% chance to increase your spell damage and healing by 80 for 30 sec when you kill a target that gives experience or honor. This effect cannot occur more than once every 10 seconds. (Proc chance: 50%, 10s cooldown)\nSell Price:" }
