entries[32775] = { ["name"] = "Deepdiving Pearl", ["text"] = "Requires Level 50\n\nUse: Swallow the pearl, granting the imbiber the ability to breath water and greatly increased swim speed. Lasts 30 sec. (1 Min Cooldown)\nSell Price:" }
